        (Test-ExtractedFolderHasContent -Path $empty) | Should -BeFalse
        Set-Content -LiteralPath (Join-Path $occupied '.hidden') -Value 'present'
        (Test-ExtractedFolderHasContent -Path $occupied) | Should -BeTrue
    }
}

