        Mock Write-Log {}
        Mock Write-TpmCompactExtractionProgress {
            [void]$script:dgVoodooPresetProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete })
        }
        try {
