        $h1 = (Get-FileHash -LiteralPath $fx -Algorithm SHA256).Hash; $h2 = (Get-FileHash -LiteralPath $fxh -Algorithm SHA256).Hash
        Mock Acquire-TpmReShadeApprovedEffect { [pscustomobject]@{ StagingRoot=$stage; Files=@(
